  "Treatments compared after removing the blocking factors." = "تُقارن المعالجات بعد إزالة عوامل التقطيع.",
  "Estimated missing value (approximate)" = "القيمة المفقودة المقدَّرة (تقريبي)", "Exact (general regression significance test)" = "دقيق (اختبار دلالة الانحدار العام)",
  "Kendall's W" = "W كندال", "Ranks the responses within each block." = "يرتّب الاستجابات داخل كل قطاع.",
