  "Level of the first factor named in the panel" = "مستوى العامل الأول المذكور في اللوحة",
  "Parallel lines: no interaction · Crossing or fanning lines: interaction" = "خطوط متوازية: لا تفاعل · خطوط متقاطعة أو متباعدة: تفاعل",
  "One line per level of the second factor (labelled) · Parallel: no interaction" = "خط لكل مستوى من العامل الثاني (مسمّى) · متوازية: لا تفاعل",
  "Level" = "المستوى",
  # samples
  "two-sided" = "ثنائي الطرف", "Positive signs" = "الإشارات الموجبة",
  "At least 2 values are needed." = "يلزم قيمتان على الأقل.", "One-sample z-test" = "اختبار z لعيّنة واحدة", "Cohen's d" = "d كوهين", "Pseudo-median" = "الوسيط الزائف",
