  "Quade test" = "اختبار كويد", "Weights blocks by their range; often more powerful with few treatments." = "يزن القطاعات بمداها؛ وهو غالبًا أقوى مع عدد قليل من المعالجات.",
  "Pairwise Wilcoxon signed-rank (Bonferroni)" = "ويلكوكسون للرتب الإشارية الزوجي (بونفيروني)", "Rank test on residuals" = "اختبار رتب على البواقي",
  "Pairwise Wilcoxon on ranks (Bonferroni)" = "ويلكوكسون الزوجي على الرتب (بونفيروني)", "Dunn test on ranks (Holm)" = "اختبار دن على الرتب (هولم)"
)

ar_tpl(
  "Permutation p-value (10,000 resamples, as in the class script): %s" = "القيمة p بالتبديل (10,000 إعادة سحب، كما في برنامج المحاضرة): $1",
