  "Rank the %d treatments within each of the b = %d blocks, then add the ranks of each treatment: %s" = "رتّب المعالجات الـ$1 داخل كل قطاع من القطاعات b = $2، ثم اجمع رتب كل معالجة: $3",
  "Corrected for ties within blocks: χ²r = %s" = "بعد تصحيح الروابط داخل القطاعات: χ²r = $1",
  "df = k − 1 = %d;   χ²r is compared with the χ² distribution" = "درجات الحرية = k − 1 = $1؛   تُقارن χ²r بتوزيع χ²",
