  "H = 12 / (N(N + 1)) × Σ Rᵢ²/nᵢ − 3(N + 1) on the ranked residuals = %s,   df = k − 1 = %d" = "H = 12 / (N(N + 1)) × Σ Rᵢ²/nᵢ − 3(N + 1) على رتب البواقي = $1،   درجات الحرية = k − 1 = $2",
  "The test '%s' is not available for this design." = "الاختبار «$1» غير متاح لهذا التصميم.",
