  "Factorial design in a Graeco-Latin square: the %d factors are crossed and the combinations are placed by row, column and Greek letter." = "تصميم عاملي في مربع لاتيني يوناني: العوامل الـ$1 متقاطعة وتُوزَّع التوليفات بحسب الصف والعمود والحرف اليوناني.",
  "The parametric test (%s) is always run first, for the main effect of each factor and for their interaction%s. If an assumption check fails afterwards, the %s is used." = "يُجرى الاختبار المعلمي ($1) دائمًا أولًا، للأثر الرئيسي لكل عامل ولتفاعلهما$2. وإذا فشل فحص أحد الافتراضات بعد ذلك يُستخدم $3.",
  "F test for %s" = "اختبار F لـ$1", "Levels of %s" = "مستويات $1", "Each effect: %s" = "كل أثر: $1",
  "N = %d observations; %s treatment combinations; ȳ... = %s" = "N = $1 مشاهدة؛ $2 توليفة معالجات؛ ȳ... = $3",
  "Rank all N = %d observations together (ties get the average rank); the variance of the ranks is MS_T = %s." = "رتّب جميع المشاهدات N = $1 معًا (تأخذ الروابط متوسط الرتب)؛ وتباين الرتب هو MS_T = $2.",
  "Fit the blocking factors only (%s) and rank the N = %d residuals; MS_T = variance of these ranks = %s." = "نلائم عوامل التقطيع فقط ($1) ونرتّب البواقي وعددها N = $2؛ و MS_T = تباين هذه الرتب = $3.",
  "Permutation p-values (%d resamples of the ranked residuals): %s" = "قيم p بالتبديل ($1 إعادة سحب لرتب البواقي): $2",
  "Rank the %d treatment combinations within each of the m = %d blocks (ties get the average rank), then add the ranks of each combination over the blocks." = "رتّب توليفات المعالجات الـ$1 داخل كل قطاع من القطاعات m = $2 (تأخذ الروابط متوسط الرتب)، ثم اجمع رتب كل توليفة عبر القطاعات.",
  "Correction for ties within blocks: divide by %s." = "تصحيح الروابط داخل القطاعات: القسمة على $1.",
  "Removes %s, ranks what is left, and compares %s with a permutation test (10,000 resamples), as in the class script." = "يزيل $1 ويرتّب ما تبقّى ويقارن $2 باختبار تبديلي (10,000 إعادة سحب) كما في برنامج المحاضرة.",
  "Rank test on residuals (%s)" = "اختبار رتب على البواقي ($1)",
  "F test (var %s / var %s)" = "اختبار F (تباين $1 / تباين $2)",
  "Uses the known population standard deviation σ = %s." = "يستخدم الانحراف المعياري المعلوم للمجتمع σ = $1.",
